import { loadFont } from "@remotion/google-fonts/Outfit";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// HIGIGESTOR · ANÚNCIO 01 v6 (revisão do diretor da v5): celular sem widget de clima e com tela coerente (Boa noite, João · 3
// atendimentos · mesma data do bloqueio), respiro sob "e caderno?" e foto limpa (sem microtexto), gancho com impulso e sofá enchendo a
// coluna, tela própria de orçamentos e transições variadas, virada de cor no "Teste grátis" (azul da marca inunda), preço legível.
// HIGIGESTOR · ANÚNCIO 01 v5: pedido — menos fundo chapado, sem o H atrás da marca, mais fotos de pessoas com motions.
// Fotos do próprio Instagram do cliente (mão com o celular e notificações, homem com o ícone do H, pulso com o relógio, dedo nos
// ícones, sofá sujo): em tela cheia com câmera andando, cópia desfocada cobrindo o quadro, motions da marca por cima.
// HIGIGESTOR · ANÚNCIO 01 v4 · REFEITO NA IDENTIDADE DO INSTAGRAM @suamarca: fundo preto-azulado com luz azul/violeta, destaque
// em degradê no próprio texto (sem tarja), ícones de vidro com contorno neon, o H de vidro do perfil na apresentação. Neon = identidade.
// Mesmo roteiro, voz e tempos da v3; correções das revisões mantidas (área segura, telas tratadas, preço nítido, final enxuto).
// HIGIGESTOR · ANÚNCIO 01 v3 (2ª revisão): telas sem "DEMO" e sem a queda de 100%, celular em "direto pelo celular", preço nítido
// no "trinta e sete", final só com logo + botão + site, saídas de texto limpas, entradas variadas e moldura sem brilho.
// HIGIGESTOR · ANÚNCIO 01 v2 (revisão do diretor): gancho grande no quadro 0, balões longe dos botões do Instagram, pilha do
// problema centrada, telas do app com dados numa janela grande com zoom por palavra, destino na chamada (higigestor.com).
// HIGIGESTOR · ANÚNCIO 01 "Sua empresa no controle" (cliente João Victor). Roteiro do cliente (gancho, problema, solução, CTA),
// voz o locutor (src/anuncio01/voz-v1-cortada.wav: as pausas longas foram encurtadas para 0,25 s, sem acelerar), 9:16 stories.
// Mesma identidade dos vídeos anteriores (marinho, azul #0B5FF5 → violeta #6A40F5, Outfit, telas reais do app só na solução),
// com abertura própria: um sofá sendo higienizado vira conversa e caderno.
// Padrão das revisões: tudo num PALCO de 1080x1150 que fica em y 300–1450 (coluna x 120–960); a pílula de destaque tem pelo
// menos o dobro do apoio; preço sem contagem passando por valores que não existem.
// Tempos = tempos da voz cortada (t = 0 é o começo do wav; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const HA6_FPS = 30;
const LEAD = 0.2;
export const HA6_FRAMES = Math.round(29.8 * HA6_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.25));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const fr = (s: number) => Math.round((s + LEAD) * HA6_FPS);

const INK = "#070E24";
const NAVY = "#0B1A35";
const NAVY2 = "#111F42";
const BLUE = "#0B5FF5";
const VIOLET = "#6A40F5";
const GRAD = `linear-gradient(100deg, ${BLUE} 0%, ${VIOLET} 100%)`;
const MIST = "#F4F6FC";
const SOFT = "#9DA9D6";
const WHITE = "#FFFFFF";
const GREEN = "#22C55E";
const RED = "#E5484D";
const BG = "#03050D";
const HLG = "linear-gradient(90deg, #4FB3FF 0%, #2F6BFF 45%, #8B5CF6 100%)";
const REDG = "linear-gradient(90deg, #FF6B6B 0%, #E5484D 100%)";
const NEON = "rgba(96,130,255,0.95)";
// foto do perfil: cópia desfocada cobrindo o quadro + a foto inteira (1080x1335) com câmera andando; filhos em coordenadas da foto
const PY = (1920 - 1335) / 2;
const Photo: React.FC<{ src: string; t: number; a: number; b: number; z0?: number; z1?: number; ox?: number; oy?: number; sharp?: boolean; dy?: number; children?: React.ReactNode }> = ({ src, t, a, b, z0 = 1, z1 = 1.12, ox = 0.5, oy = 0.5, sharp = true, dy = 0, children }) => {
  const z = z0 + (z1 - z0) * io(t, a, b);
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      <Img src={staticFile(`joao-victor/${src}.png`)} style={{ position: "absolute", left: (1080 - 1553 * z) / 2, top: (1920 - 1920 * z) / 2, width: 1553 * z, height: 1920 * z, objectFit: "cover", filter: `blur(${sharp ? 40 : 26}px) brightness(${sharp ? 0.45 : 0.5})` }} />
      {sharp ? (
        <div style={{ position: "absolute", left: 0, top: PY + dy, width: 1080, height: 1335, transform: `scale(${z.toFixed(4)})`, transformOrigin: `${(ox * 1080).toFixed(0)}px ${(oy * 1335).toFixed(0)}px` }}>
          <Img src={staticFile(`joao-victor/${src}.png`)} style={{ position: "absolute", inset: 0, width: 1080, height: 1335 }} />
          {children}
        </div>
      ) : null}
      {/* escurece em cima e embaixo, onde entra o texto */}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(3,5,13,0.88) 0%, rgba(3,5,13,0.55) 26%, rgba(3,5,13,0) 46%, rgba(3,5,13,0) 73%, rgba(3,5,13,0.97) 82%, rgba(3,5,13,0.97) 100%)" }} />
    </AbsoluteFill>
  );
};
// fundo da identidade: preto-azulado com dois focos de luz (azul e violeta) que andam devagar
const Glow: React.FC<{ t: number; tint?: string }> = ({ t, tint }) => (
  <AbsoluteFill style={{ background: BG }}>
    <div style={{ position: "absolute", left: -300 + Math.sin(t * 0.35) * 80, top: 80 + Math.cos(t * 0.3) * 60, width: 1100, height: 1100, borderRadius: 1100, background: `radial-gradient(circle, ${tint ?? "rgba(47,107,255,0.42)"} 0%, rgba(47,107,255,0) 65%)` }} />
    <div style={{ position: "absolute", left: 380 + Math.cos(t * 0.3) * 80, top: 980 + Math.sin(t * 0.4) * 70, width: 1100, height: 1100, borderRadius: 1100, background: "radial-gradient(circle, rgba(139,92,246,0.42) 0%, rgba(139,92,246,0) 65%)" }} />
  </AbsoluteFill>
);

// ───────── texto pela máscara (tamanho por linha; folga embaixo para j, p, g) ─────────
type L = [string, number, boolean?, number?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlBg?: string; pillText?: string }> = ({ t, items, size, top, color = WHITE, out, hlBg = GRAD, pillText = WHITE }) => {
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - o, transform: `translateY(${(-o * 40).toFixed(1)}px)` }}>
      {items.map(([w, at, hl, sz], i) => {
        const z = sz ?? size;
        const e = k(t, at, 0.45);
        return (
          <div key={i} style={{ overflow: "hidden", padding: `${z * 0.04}px ${z * 0.08}px ${z * 0.24}px`, marginBottom: -z * 0.14, ...(hl ? { transform: `scale(${(0.86 + 0.14 * pop(t, at, 0.5)).toFixed(4)})` } : {}) }}>
            <div style={{ fontFamily: F, fontWeight: 800, fontSize: z, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? "transparent" : color, transform: `translateY(${((1 - e) * 130).toFixed(2)}%)`, ...(hl ? { ...(hlBg === WHITE ? { color: WHITE, textShadow: "0 6px 30px rgba(10,20,80,0.45)" } : { backgroundImage: hlBg === RED ? REDG : HLG, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" }), padding: `0 ${z * 0.04}px`, filter: hlBg === WHITE ? undefined : `drop-shadow(0 0 ${(z * 0.18).toFixed(0)}px ${hlBg === RED ? "rgba(229,72,77,0.55)" : "rgba(70,110,255,0.6)"})` } : {}) }}>
              {w}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// ───────── palco: 1080x1150 em y 300–1450 ─────────
const St: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ position: "absolute", left: 0, top: 300, width: 1080, height: 1150 }}>{children}</div>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string }>;
const sv = (s: number, c: string, ch: React.ReactNode) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoUsers: Ico = ({ s, c }) => sv(s, c, <><circle cx="9" cy="8.5" r="3.5" /><path d="M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.9 6.5 5.5M16 5.3a3.5 3.5 0 010 6.4M18.5 14.9c1.7.8 2.7 2.5 3 5.1" /></>);
const IcoCal: Ico = ({ s, c }) => sv(s, c, <><rect x="3.5" y="5" width="17" height="15.5" rx="3" /><path d="M3.5 10h17M8 3v4M16 3v4" /></>);
const IcoDoc: Ico = ({ s, c }) => sv(s, c, <><path d="M6 3h8l4 4v14H6z" /><path d="M14 3v4h4M9 12h6M9 16h4" /></>);
const IcoMoney: Ico = ({ s, c }) => sv(s, c, <><rect x="2.5" y="6" width="19" height="12" rx="2.5" /><circle cx="12" cy="12" r="2.6" /><path d="M6 9.5v5M18 9.5v5" /></>);
const IcoPlus: Ico = ({ s, c }) => sv(s, c, <path d="M12 5v14M5 12h14" />);
const IcoCheck: Ico = ({ s, c }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />);

// ───────── celular com a gravação de tela do cliente ─────────
const SW = 384, SH = 832;
const Phone: React.FC<{ w: number; children: React.ReactNode }> = ({ w, children }) => {
  const pad = w * 0.035;
  const sw = w - pad * 2, sh = (sw * SH) / SW;
  return (
    <div style={{ width: w, height: sh + pad * 2, borderRadius: w * 0.14, background: "#1A2448", padding: pad, boxSizing: "border-box", boxShadow: "0 60px 120px rgba(0,0,0,0.45), 0 0 0 2px rgba(157,169,214,0.25)" }}>
      <div style={{ width: sw, height: sh, borderRadius: w * 0.11, overflow: "hidden", position: "relative", background: "#0E1220" }}>{children}</div>
    </div>
  );
};
// trecho de vídeo que começa a tocar quando aparece
const Clip: React.FC<{ src: string; at: number }> = ({ src, at }) => (
  <Sequence from={fr(at)} layout="none">
    <OffthreadVideo src={staticFile(`joao-victor/${src}.mp4`)} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
  </Sequence>
);

const Symbol: React.FC<{ size: number; t: number; at: number }> = ({ size, t, at }) => {
  const e = pop(t, at, 0.55);
  return <Img src={staticFile("joao-victor/simbolo.png")} style={{ width: size, height: size * (349 / 364), opacity: Math.min(1, e * 2), transform: `scale(${(0.4 + 0.6 * e).toFixed(4)}) rotate(${((1 - e) * -18).toFixed(2)}deg)` }} />;
};

// ───────── desenhos da abertura e do problema ─────────
const Sofa: React.FC<{ w: number; t: number }> = ({ w, t }) => {
  const h = w * 0.62;
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <div style={{ position: "absolute", left: w * 0.1, right: w * 0.1, top: 0, height: h * 0.55, borderRadius: w * 0.07, background: VIOLET }} />
      <div style={{ position: "absolute", left: 0, width: w * 0.16, top: h * 0.3, height: h * 0.55, borderRadius: w * 0.06, background: BLUE }} />
      <div style={{ position: "absolute", right: 0, width: w * 0.16, top: h * 0.3, height: h * 0.55, borderRadius: w * 0.06, background: BLUE }} />
      <div style={{ position: "absolute", left: w * 0.12, right: w * 0.12, top: h * 0.48, height: h * 0.34, borderRadius: w * 0.05, background: "#8466F7" }} />
      <div style={{ position: "absolute", left: w * 0.5 - 2, width: 4, top: h * 0.5, height: h * 0.3, background: "rgba(7,14,36,0.25)" }} />
      {[0.14, 0.82].map((x, i) => <div key={i} style={{ position: "absolute", left: w * x, top: h * 0.85, width: w * 0.04, height: h * 0.15, borderRadius: 6, background: "#33406B" }} />)}
      {/* espuma da higienização: bolhas que sobem e brilhos que piscam */}
      {[...Array(9)].map((_, i) => {
        const p = (((t * 0.55 + i / 9) % 1) + 1) % 1;
        const x = w * (0.15 + ((i * 37) % 70) / 100), r = 16 + (i % 3) * 10;
        return <div key={i} style={{ position: "absolute", left: x - r, top: h * 0.45 - p * h * 0.75 - r, width: r * 2, height: r * 2, borderRadius: r * 2, border: "4px solid rgba(255,255,255,0.75)", background: "rgba(255,255,255,0.12)", opacity: Math.sin(p * Math.PI) }} />;
      })}
      {[[0.22, 0.12], [0.7, 0.05], [0.5, 0.3]].map(([x, y], i) => {
        const s = 0.5 + 0.5 * Math.sin(t * 5 + i * 2);
        return <svg key={i} width={70} height={70} viewBox="0 0 24 24" style={{ position: "absolute", left: w * x, top: h * y - 60, transform: `scale(${s.toFixed(3)})` }}><path d="M12 2l2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z" fill={WHITE} /></svg>;
      })}
    </div>
  );
};
const Bubble: React.FC<{ w: number; me: boolean; n?: number }> = ({ w, me, n }) => (
  <div style={{ position: "relative", width: w, padding: "28px 32px", boxSizing: "border-box", borderRadius: 40, borderBottomLeftRadius: me ? 40 : 8, borderBottomRightRadius: me ? 8 : 40, background: me ? "#D3F8C9" : WHITE, boxShadow: "0 20px 44px rgba(0,0,0,0.35)" }}>
    {[0.9, 0.55].map((f, i) => <div key={i} style={{ width: `${f * 100}%`, height: 16, borderRadius: 8, background: me ? "#8CC97D" : "#C3CCD8", marginBottom: i ? 0 : 16 }} />)}
    {n ? <div style={{ position: "absolute", right: -18, top: -18, width: 60, height: 60, borderRadius: 60, background: GREEN, color: WHITE, fontFamily: F, fontWeight: 800, fontSize: 32, display: "flex", alignItems: "center", justifyContent: "center" }}>{n}</div> : null}
  </div>
);
const Notebook: React.FC<{ w: number }> = ({ w }) => (
  <div style={{ width: w, height: w * 1.25, position: "relative" }}>
    <div style={{ position: "absolute", inset: 0, borderRadius: w * 0.06, background: "#F3E3B5", border: `${w * 0.012}px solid #D9BC5C`, boxSizing: "border-box", boxShadow: "0 30px 60px rgba(0,0,0,0.4)" }}>
      {[...Array(6)].map((_, i) => <div key={i} style={{ position: "absolute", left: w * 0.2, top: w * (0.22 + i * 0.15), width: w * (i % 3 === 1 ? 0.45 : 0.65), height: w * 0.03, borderRadius: w, background: "#C9A94A", transform: `rotate(${(i % 2 ? -2 : 1.5)}deg)` }} />)}
    </div>
    {[...Array(7)].map((_, i) => <div key={i} style={{ position: "absolute", left: -w * 0.045, top: w * (0.12 + i * 0.16), width: w * 0.13, height: w * 0.05, borderRadius: w, background: SOFT, border: `${w * 0.008}px solid ${NAVY}`, boxSizing: "border-box" }} />)}
  </div>
);
const IcoUserQ: Ico = ({ s, c }) => sv(s, c, <><circle cx="9" cy="8" r="3.5" /><path d="M2.5 20c.6-3.6 3.2-5.5 6.5-5.5 1.6 0 3 .4 4.1 1.2" /><path d="M17 13.5a2.3 2.3 0 114 1.5c-.8.6-1.7 1-1.7 2M19.3 20.3v.2" /></>);
const IcoDocClock: Ico = ({ s, c }) => sv(s, c, <><path d="M13 21H6V3h8l4 4v4" /><path d="M14 3v4h4" /><circle cx="17.5" cy="17" r="4" /><path d="M17.5 15v2l1.4 1" /></>);
const IcoCalMess: Ico = ({ s, c }) => sv(s, c, <><rect x="3.5" y="5" width="17" height="15.5" rx="3" /><path d="M3.5 10h17M8 3v4M16 3v4M8 13.5l3 3M11 13.5l-3 3M14 14h3M15 17.5h2" /></>);

// ───────── cena 1 · gancho: o sofá sendo higienizado; depois a conversa e o caderno ─────────
const T2 = 5.85, T3 = 12.6, T3B = 14.35, T4 = 20.85, T4B = 23.1, T4C = 26.7;
// ícones de vidro com contorno neon (como os do perfil): sofá, conversa e caderno
const IcoSofa: Ico = ({ s, c }) => sv(s, c, <><path d="M5 11V8.5A2.5 2.5 0 017.5 6h9A2.5 2.5 0 0119 8.5V11" /><path d="M3 12.5a1.5 1.5 0 013 0V14h12v-1.5a1.5 1.5 0 013 0V17a1 1 0 01-1 1H4a1 1 0 01-1-1z" /><path d="M6 18v1.5M18 18v1.5" /></>);
const IcoChat2: Ico = ({ s, c }) => sv(s, c, <><path d="M4 5h16v11H9l-5 4z" /><path d="M8 9.5h8M8 12.5h5" /></>);
const IcoNote: Ico = ({ s, c }) => sv(s, c, <><rect x="5" y="3.5" width="14" height="17" rx="2" /><path d="M9 8h6M9 11.5h6M9 15h4M3.5 7h3M3.5 12h3M3.5 17h3" /></>);
const GlassTile: React.FC<{ size: number; on: number; I: Ico }> = ({ size, on, I }) => (
  <div style={{ width: size, height: size, borderRadius: size * 0.26, background: `rgba(47,107,255,${(0.05 + 0.17 * on).toFixed(3)})`, border: `${Math.max(2, size * 0.012)}px solid rgba(110,140,255,${(0.3 + 0.65 * on).toFixed(3)})`, boxShadow: `0 0 ${(size * 0.22 * on).toFixed(0)}px rgba(80,110,255,${(0.7 * on).toFixed(2)}), inset 0 0 ${(size * 0.15 * on).toFixed(0)}px rgba(120,150,255,${(0.45 * on).toFixed(2)})`, display: "flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box" }}>
    <div style={{ display: "flex", filter: on > 0.05 ? `drop-shadow(0 0 ${(size * 0.08 * on).toFixed(0)}px rgba(120,170,255,0.9))` : undefined, opacity: 0.45 + 0.55 * on }}><I s={size * 0.56} c={WHITE} /></div>
  </div>
);
const S1: React.FC<{ t: number }> = ({ t }) => {
  const ph = io(t, 1.9, 2.3);
  const card = pop(t, -0.15, 0.7);
  return (
    <AbsoluteFill>
      <Glow t={t} />
      {t > 1.85 ? (
        <AbsoluteFill style={{ opacity: ph }}>
          <Photo src="ig-mao-celular-limpo" t={t} a={1.9} b={T2 + 0.4} z0={0.93} z1={0.96} ox={0.5} oy={0.5} dy={205}>
            {([[222, 730, 858, 858, 4.22], [222, 886, 858, 1016, 5.05]] as number[][]).map(([x0, y0, x1, y1, at], i) => (
              <div key={i} style={{ position: "absolute", left: x0, top: y0, width: x1 - x0, height: y1 - y0, borderRadius: 46, border: `6px solid ${NEON}`, boxShadow: "0 0 46px rgba(80,110,255,0.85), inset 0 0 24px rgba(80,110,255,0.4)", opacity: k(t, at, 0.25), transform: `scale(${(1 + 0.05 * bump(t, at, 0.4)).toFixed(4)})` }} />
            ))}
          </Photo>
        </AbsoluteFill>
      ) : null}
      <St>
        <Lines t={t} top={20} size={60} items={[["Você trabalha com", -0.2]]} out={1.85} />
        <div style={{ position: "absolute", inset: 0, transform: `scale(${(1.12 - 0.12 * pop(t, -0.2, 0.5)).toFixed(4)})`, transformOrigin: "540px 170px", opacity: 1 - lin(t, 1.85, 2.0) }}><Lines t={t} top={90} size={142} items={[["higienização", -0.2, true, 130]]} /></div>
        <div style={{ position: "absolute", left: 120, top: 330, width: 840, height: 800, borderRadius: 56, overflow: "hidden", border: `5px solid ${NEON}`, boxShadow: "0 0 60px rgba(80,110,255,0.6)", opacity: Math.min(1, card * 2) * (1 - ph), transform: `translateY(${((1 - card) * 300).toFixed(1)}px) scale(${(0.55 + 0.45 * card + 0.05 * bump(t, 0.55, 0.4)).toFixed(4)}) rotate(${((1 - card) * -14).toFixed(2)}deg)` }}>
          <Img src={staticFile("joao-victor/ig-sofa-sujo.png")} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(1.0 + 0.3 * lin(t, -0.2, 2)).toFixed(4)})` }} />
        </div>
        <Lines t={t} top={0} size={80} items={[["e ainda controla", 1.98], ["seus serviços pelo", 2.3]]} out={3.98} />
        <Lines t={t} top={-20} size={64} items={[["WhatsApp", 4.22, true, 116], ["e caderno?", 5.05, true, 116]]} />
      </St>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · problema (virada para o claro): três cartões riscados e o dinheiro escorrendo ─────────
const PROBS: [Ico, string, number, number][] = [[IcoUserQ, "Cliente perdido", 5.94, 6.4], [IcoDocClock, "Orçamento esquecido", 7.08, 7.75], [IcoCalMess, "Agenda bagunçada", 8.45, 9.2]];
